mapper.select:
SELECT COUNT(*)
FROM COMMENT
WHERE comment_id = #{commentId} AND post_id = #{postId}

mapper.update:
UPDATE COMMENT
SET
    content = #{dto.content},
    parent_comment_id = #{dto.parentCommentId}
WHERE comment_id = #{commentId}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM COMMENT
WHERE comment_id = #{commentId}
  AND user_id = #{userId}

mapper.update:
UPDATE COMMENT
SET like_count = GREATEST(0, like_count + #{delta})
WHERE comment_id = #{commentId}
